                    onLogout();
                  }}
                  className="block w-full rounded-lg px-3 py-2 text-left text-sm text-danger hover:bg-background focus:outline-none focus-visible:ring-2 focus-visible:ring-primary/30"
                >
                  {t('Log out')}
